from pathlib import Path
import pcbnew as p,json,hashlib,time
R=Path('/tmp/v7-serial-legs-plus-two-labels');Q=R/'filled/pcb/maru60.kicad_pcb';H=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();before=H(Q);b=p.LoadBoard(str(Q));assert p.GetBuildVersion()=='9.0.2+dfsg-1';ct=json.loads((R/'BUILD_CONTRACT.json').read_text());idx={q.m_Uuid.AsString():q for q in b.GetTracks()}
